		if (err instanceof Error && (err.message.includes("تتجاوز") || err.message.includes("غير موجود") || err.message.includes("ملغاة") || err.message.includes("محظور"))) throw err;
		handleFirestoreError(err, OperationType.WRITE, "returns");
